{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by submitting documents and observing that the system returns exactly one category and a confidence score within the specified range."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score requires statistical evaluation and calculation on a held-out dataset."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing behavior is verified by submitting documents with low confidence scores and observing that they are directed to the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing the service with 50 requests per second and measuring the response times to check the 95th percentile."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The logging requirement is verified by inspecting the recorded logs or database entries to ensure the model version, input hash, and predicted category are present."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting deviation in category distribution requires calculating the population stability index, which is a statistical analysis task."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The functionality is verified by submitting a document and observing that the response includes the three specified text passages."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between different language subsets requires statistical analysis of the model's performance on those specific groups."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that all specified fields are captured."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct colors for the four triage categories are verified by running the application and visually observing the UI elements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by inputting valid and invalid vital sign values to observe correct recording and rejection behavior."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by disabling network connectivity and creating 500 records to ensure the application remains functional and stores them locally."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by simulating conflicting edits, restoring connectivity, and observing the synchronization and conflict resolution behavior."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The requirement is verified by inspecting the code or configuration to confirm that AES-256 encryption is applied to stored casualty data."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The requirement is verified by a user wearing surgical gloves operating the application to demonstrate that all functions are accessible."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by running the application under the defined usage profile and measuring the battery life to ensure it lasts at least 8 hours."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sistemin çalıştırılması ve sensör girdilerinin verilmesiyle ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı gözlemlenebilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarını ekranda görüntüleyebilmesi, sistemin çalıştırılıp gözlemlenerek gösterilebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Zamanlayıcı mantığı, girdi akışının durdurulması ve belirli sürelerin beklenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği çalıştırılarak gözlenebilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj iletim süresi ve durum bildirimi, mesaj gönderilip alıcı tarafında gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Kayıt tutma mekanizmasının değiştirilemezlik özelliği ve log yapısı, kod veya yapılandırma incelemesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Sunucu arızası senaryosu oluşturularak devralma süresi ve veri bütünlüğü test edilebilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek veya simüle edilmiş kimlik doğrulama girdileri verilerek gözlemlenmelidir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı testleri ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık kilit süresinin, senaryo tabanlı testler ile kontrol edilmelidir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının, farklı girdi kombinasyonları ile sisteme yüklenerek test edilmesi gerekir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanınca benzersiz takip numarası üretimi ve e-posta ile bildirim gönderiminin, uçtan uca test senaryoları ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme, 30 günlük saklama süresi ve kaldığı yerden devam etme işlevinin, zaman ve durum geçişleri içeren testler ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzünün ve kodun erişilebilirlik standartlarına göre gözle denetlenerek (inceleme) doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklandığının, altyapı yapılandırması ve veri akış belgelerinin gözle denetlenerek (inceleme) doğrulanması gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, yük testi senaryolarında sistemin davranışı gözlemlenerek doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "99. yüzdelik dilimdeki gecikme metriklerinin istatistiksel olarak hesaplanması ve belirli bir yük altında performansın modellenmesi/benzetimi gerektiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman aşımı senaryosunun (5 saniye) simüle edilerek sistemin isteği sonlandırıp HTTP 504 döndürme davranışının gözlemlenmesi, test yöntemiyle doğrulanabilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yeniden başlatma olmadan yapılandırma değişikliğinin uygulanması ve devam eden isteklerin düşmemesi, sistem çalışırken yapılandırma güncellenip istek akışı izlenerek test edilebilir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin işlenmesinin ardından günlük dosyasındaki kayıtların beklenen alanları (izleme kimliği, süre vb.) içerip içermediğinin kontrol edilmesi, test yöntemiyle doğrulanır."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, uzun vadeli istatistiksel veri analizi ve planlı bakım pencerelerinin dışlanması gerektirdiği için analiz yöntemi seçilir."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "KMU-007: Arayüzün WCAG 2.1 AA uyumluluğunun test edilmesi",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "KMU-007 gereksinimi için test ortamı hazırdır ve ekran okuyucu ile tarayıcı uyumluluk araçları kurulmuştur.",
      "test_inputs": "Ana sayfa, giriş formu ve başvuru formu URL'leri.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Sistemde bir ekran okuyucu (ör. JAWS, NVDA) kullanılarak ana sayfa gezilir.",
          "expected": "Tüm başlık, bağlantı ve form öğeleri ekran okuyucu tarafından doğru olarak okunur ve anlaşılmaz."
        },
        {
          "no": 2,
          "action": "Klavye tuşları (Tab, Shift+Tab, Enter) kullanılarak sayfadaki tüm etkileşimli öğelere erişilir.",
          "expected": "Odak sırası mantıklıdır, klavye tuzağı yoktur ve tüm işlevler klavye ile kullanılabilir."
        },
        {
          "no": 3,
          "action": "Sayfa içeriğinin kontrast oranı ve metin boyutu, tarayıcı zoom ile %200'e büyütülerek kontrol edilir.",
          "expected": "Metinler okunabilirliğini korur, içerik kaymaz ve WCAG 2.1 AA kontrast gereksinimleri karşılanır."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Tanımlı bölgeye girişte görsel ve sesli uyarı verilmesi",
      "covers": [
        "KK-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem aktif durumda, operatör arayüzü açık ve en az bir tanımlı bölge yapılandırılmıştır.",
      "test_inputs": "Tanımlı bölge sınırları içinde hareket eden bir iz (target) verisi.",
      "assumptions": "Sesli uyarı sistemi (hoparlör) bağlı ve çalışır durumdadır.",
      "steps": [
        {
          "no": 1,
          "action": "Tanımlı bölgenin dışındaki bir iz, bölge sınırlarına doğru hareket ettirilir.",
          "expected": "Uyarı verilmez, iz normal şekilde izlenir."
        },
        {
          "no": 2,
          "action": "İz, tanımlı bölge sınırlarının içine girer.",
          "expected": "Operatör arayüzünde görsel uyarı (örneğin renkli vurgulama veya ikon) belirir ve sesli uyarı çalınır."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Metin mesajının 2 saniye içinde iletilmesi ve durumun gösterilmesi",
      "covers": [
        "KK-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "İki operatör oturumu (Gönderen ve Alıcı) aktiftir ve sistem ağ bağlantısı stabil durumdadır.",
      "test_inputs": "Gönderen operatör tarafından Alıcı operatöre gönderilen kısa bir metin mesajı.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Gönderen operatör, Alıcı operatöre bir metin mesajı gönderir.",
          "expected": "Mesaj gönderimi başlar."
        },
        {
          "no": 2,
          "action": "Alıcı operatörün ekranında mesajın görünmesi beklenir.",
          "expected": "Mesaj, gönderimden itibaren en geç 2 saniye içinde Alıcı operatörün ekranında görünür."
        },
        {
          "no": 3,
          "action": "Gönderen operatörün arayüzünde iletim durumu kontrol edilir.",
          "expected": "Mesajın başarıyla iletildiğini gösteren bir durum bilgisi (örneğin 'İletildi' veya onay ikonu) gönderene gösterilir."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and a test casualty record is available to be created.",
      "test_inputs": "A valid casualty record containing name, age, and injury details.",
      "assumptions": "File system access permissions allow reading the application's storage directory.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record in the application with test data (e.g., Name: 'Test Patient', Age: 30).",
          "expected": "The record is successfully saved and appears in the casualty list."
        },
        {
          "no": 2,
          "action": "Navigate to the device's file system storage where the application saves its data.",
          "expected": "The data file associated with the casualty record is located."
        },
        {
          "no": 3,
          "action": "Open the data file using a standard text editor or hex viewer.",
          "expected": "The content is not human-readable plaintext; the data is encrypted."
        },
        {
          "no": 4,
          "action": "Verify the encryption algorithm used by the application via configuration logs or technical documentation accessible from the device.",
          "expected": "The configuration confirms that AES-256 is the encryption standard applied to the stored casualty data."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged to 100%. The 'defined usage profile' is documented and accessible (e.g., continuous triage data entry, screen on, Wi-Fi active).",
      "test_inputs": "None (usage profile defined by protocol).",
      "assumptions": "The 'defined usage profile' consists of: Screen brightness at 50%, Wi-Fi enabled, continuous data entry for 8 hours. If the profile is not explicitly defined in the project card, this standard field usage profile is assumed.",
      "steps": [
        {
          "no": 1,
          "action": "Charge the tablet to 100% and ensure it is fully idle for 10 minutes to stabilize battery metrics.",
          "expected": "Battery level is reported as 100%."
        },
        {
          "no": 2,
          "action": "Start the timer and begin executing the defined usage profile (e.g., continuous triage data entry, screen on, connectivity active).",
          "expected": "The application remains responsive and the battery level begins to decrease."
        },
        {
          "no": 3,
          "action": "Continue the usage profile until the 8-hour mark.",
          "expected": "The tablet is still operating, the application is functional, and the battery level is above 0%."
        },
        {
          "no": 4,
          "action": "Check the remaining battery percentage at the 8-hour mark.",
          "expected": "The battery has not depleted; the device meets the minimum 8-hour requirement."
        }
      ]
    }
  ]
}

