{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Offline operation with 500 casualty records",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed on a tablet with network connectivity disabled.",
      "test_inputs": "500 unique casualty records",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Ensure the tablet has no network connectivity.",
          "expected": "The application indicates it is offline but remains accessible."
        },
        {
          "no": 2,
          "action": "Create 500 casualty records in the application.",
          "expected": "All 500 records are successfully saved locally without errors."
        },
        {
          "no": 3,
          "action": "Retrieve and display a sample of the created records.",
          "expected": "The records are displayed correctly with all data intact."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Offline operation exceeding 500 casualty records",
      "covers": [
        "MED-004"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The application is installed on a tablet with network connectivity disabled.",
      "test_inputs": "501 unique casualty records",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Ensure the tablet has no network connectivity.",
          "expected": "The application indicates it is offline but remains accessible."
        },
        {
          "no": 2,
          "action": "Create 501 casualty records in the application.",
          "expected": "The first 500 records are saved successfully. The 501st record is saved if local storage allows, or the application handles the overflow according to its defined behavior (e.g., warning or rejection), maintaining full functionality for existing data."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Synchronization upon connectivity restoration",
      "covers": [
        "MED-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application has local records created while offline and network connectivity is restored.",
      "test_inputs": "Local records created offline",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Restore network connectivity to the tablet.",
          "expected": "The application detects connectivity and initiates synchronization with the server."
        },
        {
          "no": 2,
          "action": "Observe the synchronization process.",
          "expected": "Local records are synchronized with the server successfully."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Conflict resolution during synchronization",
      "covers": [
        "MED-005"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A casualty record exists on both the local device and the server, and both have been modified differently while offline.",
      "test_inputs": "Conflicting local and server versions of a casualty record",
      "assumptions": "",
      "steps": [
